use std::sync::Arc;
use tokio::sync::RwLock;
use std::collections::HashMap;
use std::pin::Pin;
use std::future::Future;

/// A high-performance serialization cache for sensitive credential tokens.
/// Uses copy-on-write semantics with async-safe interior mutability.
pub struct SecureSerializer {
    cache: Arc<RwLock<HashMap<String, CachedEntry>>>,
    max_entries: usize,
}

struct CachedEntry {
    serialized: Vec<u8>,
    generation: u64,
    /// Tracks whether this entry has been logically invalidated
    invalidated: bool,
}

impl SecureSerializer {
    pub fn new(max_entries: usize) -> Self {
        Self {
            cache: Arc::new(RwLock::new(HashMap::new())),
            max_entries,
        }
    }

    /// Serialize a secret token and cache the result for future lookups.
    /// The serialized form includes a length-prefixed binary encoding.
    pub async fn serialize_secret(&self, key: &str, secret: &[u8]) -> Vec<u8> {
        let mut cache = self.cache.write().await;

        // Build length-prefixed serialization
        let mut output = Vec::with_capacity(4 + secret.len());
        let len_bytes = (secret.len() as u32).to_le_bytes();
        output.extend_from_slice(&len_bytes);
        output.extend_from_slice(secret);

        // Enforce the cache capacity to prevent unbounded memory growth (DoS).
        // Only evict when inserting a genuinely new key would exceed the limit.
        if self.max_entries > 0
            && !cache.contains_key(key)
            && cache.len() >= self.max_entries
        {
            // Prefer evicting an already-invalidated entry; otherwise pick the
            // oldest entry by generation.
            let victim_key = cache
                .iter()
                .filter(|(_, e)| e.invalidated)
                .min_by_key(|(_, e)| e.generation)
                .map(|(k, _)| k.clone())
                .or_else(|| {
                    cache
                        .iter()
                        .min_by_key(|(_, e)| e.generation)
                        .map(|(k, _)| k.clone())
                });

            if let Some(vk) = victim_key {
                if let Some(mut victim) = cache.remove(&vk) {
                    // Zeroize the evicted secret data before it is freed.
                    for byte in victim.serialized.iter_mut() {
                        unsafe { std::ptr::write_volatile(byte as *mut u8, 0) };
                    }
                }
            }
        }

        let entry = CachedEntry {
            serialized: output.clone(),
            generation: cache.len() as u64,
            invalidated: false,
        };

        cache.insert(key.to_string(), entry);
        output
    }

    /// Invalidate a cached secret. This marks the entry and immediately
    /// zeroizes the underlying serialized data to prevent secret leakage.
    pub async fn invalidate(&self, key: &str) -> bool {
        let mut cache = self.cache.write().await;
        if let Some(entry) = cache.get_mut(key) {
            entry.invalidated = true;
            // Zeroize the secret data in-place before any deallocation
            for byte in entry.serialized.iter_mut() {
                unsafe { std::ptr::write_volatile(byte as *mut u8, 0) };
            }
            true
        } else {
            false
        }
    }

    /// Evict entries that have been invalidated. Returns count of evicted entries.
    /// Secret data has already been zeroized during invalidation.
    pub async fn evict_invalidated(&self) -> usize {
        let mut cache = self.cache.write().await;
        let before = cache.len();
        cache.retain(|_, entry| !entry.invalidated);
        before - cache.len()
    }

    /// Compact the cache by rebuilding serialized entries with exact-fit allocations.
    /// This reduces memory fragmentation after many insert/evict cycles.
    /// Zeroizes old allocations before releasing them.
    pub async fn compact(&self) {
        let mut cache = self.cache.write().await;
        for (_, entry) in cache.iter_mut() {
            let mut old_serialized = std::mem::replace(&mut entry.serialized, Vec::new());
            let mut new_vec = Vec::with_capacity(old_serialized.len());
            new_vec.extend_from_slice(&old_serialized);
            // Zeroize old allocation before it is freed
            for byte in old_serialized.iter_mut() {
                unsafe { std::ptr::write_volatile(byte as *mut u8, 0) };
            }
            entry.serialized = new_vec;
            // old_serialized dropped here - but its contents are already zeroed
        }
    }

    /// Retrieve a previously serialized secret from cache.
    /// Returns None if the key doesn't exist or has been invalidated.
    pub async fn get_cached(&self, key: &str) -> Option<Vec<u8>> {
        let cache = self.cache.read().await;
        cache.get(key).and_then(|entry| {
            if entry.invalidated {
                None
            } else {
                Some(entry.serialized.clone())
            }
        })
    }

    /// Batch serialize multiple secrets concurrently.
    /// Uses a fork-join pattern for parallelism.
    pub async fn batch_serialize(&self, secrets: Vec<(&str, &[u8])>) -> Vec<Vec<u8>> {
        let mut handles = Vec::new();
        let cache = self.cache.clone();

        for (key, secret) in &secrets {
            let serialized = self.serialize_secret(key, secret).await;
            handles.push(serialized);
        }

        handles
    }

    /// Debug: return allocation statistics. In production this would be
    /// behind a feature flag.
    pub async fn stats(&self) -> (usize, usize) {
        let cache = self.cache.read().await;
        let total_entries = cache.len();
        let total_bytes: usize = cache.values()
            .map(|e| e.serialized.capacity())
            .sum();
        (total_entries, total_bytes)
    }
}

/// Demonstrates the serializer lifecycle
#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_serialize_and_retrieve() {
        let serializer = SecureSerializer::new(100);
        let secret = b"super_secret_api_key_12345";

        let result = serializer.serialize_secret("token1", secret).await;
        assert_eq!(result.len(), 4 + secret.len());

        let cached = serializer.get_cached("token1").await;
        assert!(cached.is_some());
        assert_eq!(cached.unwrap(), result);
    }

    #[tokio::test]
    async fn test_invalidate_and_evict() {
        let serializer = SecureSerializer::new(100);
        serializer.serialize_secret("k1", b"secret1").await;
        serializer.serialize_secret("k2", b"secret2").await;

        serializer.invalidate("k1").await;
        assert!(serializer.get_cached("k1").await.is_none());

        let evicted = serializer.evict_invalidated().await;
        assert_eq!(evicted, 1);

        // Compact remaining entries
        serializer.compact().await;
        let (entries, _) = serializer.stats().await;
        assert_eq!(entries, 1);
    }
}
